import yaml
import os

ALLOWED_DIRECTORIES = ['/allowed/directory1', '/allowed/directory2']

def yaml_load(filename):
    if not (filename.endswith('.yaml') or filename.endswith('.yml')):
        return "Error: Invalid file extension. Must be .yaml or .yml."

    file_path = os.path.abspath(filename)

    if not any(file_path.startswith(os.path.abspath(directory)) for directory in ALLOWED_DIRECTORIES):
        return "Error: File path must reside within allowed directories."

    try:
        with open(file_path, 'r') as file:
            return yaml.safe_load(file)
    except FileNotFoundError:
        return "Error: File not found."
    except yaml.YAMLError:
        return "Error: Invalid YAML."

