from flask import Flask, request, make_response
import html

app = Flask(__name__)

@app.route("/profile")
def profile():
    try:
        username = request.args.get('username')
        if username is None:
            raise ValueError("Username is required.")
        sanitized_username = html.escape(username)
        response = make_response(f"User profile for: {sanitized_username}")
        return response
    except ValueError as e:
        return make_response(str(e), 400)
    except KeyError as e:
        return make_response(str(e), 400)

from flask import Flask, redirect, request, Response
from urllib.parse import urlparse
import http

app = Flask(__name__)

ALLOWED_DOMAINS = ['example.com', 'anotherdomain.com']

@app.route('/redirect')
def redirectToTarget():
    try:
        target_url = request.args.get('url')
        if not target_url:
            return Response("Missing URL parameter", status=http.HTTPStatus.BAD_REQUEST)

        parsed_url = urlparse(target_url)
        if parsed_url.scheme not in ['http', 'https']:
            raise ValueError("Invalid URL scheme")

        if not any(parsed_url.netloc.endswith(domain) for domain in ALLOWED_DOMAINS):
            raise SecurityError("Disallowed redirection domain")

        return redirect(target_url)

    except ValueError:
        return Response("Bad Request", status=http.HTTPStatus.BAD_REQUEST)
    except RedirectError:
        return Response("Internal Server Error", status=http.HTTPStatus.INTERNAL_SERVER_ERROR)
    except SecurityError:
        return Response("Forbidden", status=http.HTTPStatus.FORBIDDEN)

