from flask import Flask, redirect, request, abort
import urllib.parse

app = Flask(__name__)

allowed_domains = ['example.com', 'anotherexample.com']

class InvalidDomainError(Exception):
    pass

class URLValidationError(Exception):
    pass

def url_validator_function(url):
    parsed_url = urllib.parse.urlparse(url)
    if not parsed_url.scheme or not parsed_url.netloc:
        raise URLValidationError("Invalid URL")
    if parsed_url.netloc not in allowed_domains:
        raise InvalidDomainError("Domain not allowed")
    return parsed_url.geturl()

@app.route('/redirect')
def redirectToTarget():
    target_url = request.args.get('url')

    try:
        validated_url = url_validator_function(target_url)
        # Log the successful redirect for audit purposes 
        app.logger.info(f'Redirecting to: {validated_url}')
        return redirect(validated_url)
    except InvalidDomainError:
        return '400 Bad Request', 400
    except URLValidationError:
        return '400 Bad Request', 400

import os
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_DIR = '/allowed_directory'

@app.route('/deleteImage', methods=['DELETE'])
def deleteImage():
    filename = request.args.get('filename')
    if filename is None or '../' in filename:
        return jsonify(message='Invalid input.'), 400

    file_path = os.path.abspath(os.path.join(ALLOWED_DIR, filename))

    if not file_path.startswith(os.path.abspath(ALLOWED_DIR)):
        return jsonify(message='Invalid input.'), 400

    try:
        os.remove(file_path)
        return jsonify(message='File deleted successfully.'), 200
    except FileNotFoundError:
        return jsonify(message='File not found.'), 404
    except PermissionError:
        return jsonify(message='Insufficient permissions.'), 403

from flask import Flask, request, send_file, abort
import os
from werkzeug.utils import safe_join

app = Flask(__name__)
whitelisted_path = "/allowed/path"
allowed_extensions = {'.txt', '.pdf'}
max_file_size = 5 * 1024 * 1024  # 5 MB

@app.route("/filedata")
def getFileData():
    filename = request.args.get('filename')
    if not filename:
        abort(400)

    if not any(filename.endswith(ext) for ext in allowed_extensions):
        abort(400)

    safe_path = safe_join(whitelisted_path, filename)
    if not safe_path.startswith(os.path.abspath(whitelisted_path)):
        abort(400)

    if os.path.exists(safe_path):
        file_size = os.path.getsize(safe_path)
        if file_size > max_file_size:
            abort(400)

        try:
            return send_file(safe_path)
        except FileNotFoundError:
            return abort(404)
        except ValueError:
            return abort(400)
        except Exception:
            return abort(500)
    else:
        return abort(404)

import tarfile
import os
import logging
import tempfile

def extract_tar(file_name):
    try:
        with tarfile.open(file_name) as tar:
            safe_extensions = ['.txt', '.csv', '.json']
            with tempfile.TemporaryDirectory() as temp_dir:
                extract_path = os.path.abspath(temp_dir)

                for member in tar.getmembers():
                    member_path = member.name

                    if not any(member_path.endswith(ext) for ext in safe_extensions):
                        logging.error(f"Unsafe file extension: {member_path}")
                        continue

                    full_path = os.path.join(extract_path, member_path)
                    if os.path.commonprefix([os.path.abspath(full_path), extract_path]) != extract_path:
                        logging.error(f"Path traversal attempt detected: {member_path}")
                        continue

                    if os.path.exists(full_path):
                        logging.error(f"File already exists and may overwrite critical file: {full_path}")
                        continue

                    try:
                        tar.extract(member, extract_path)
                    except tarfile.TarError as e:
                        logging.error(f"TarError: {str(e)} - extraction prevented.")
                        continue
                    except OSError as e:
                        logging.error(f"OSError: {str(e)} - handling gracefully.")
                        continue

    except FileNotFoundError:
        logging.error("File not found. Alerting user.")
    except tarfile.TarError as e:
        logging.error(f"TarError: {str(e)} - extraction prevented.")
    except OSError as e:
        logging.error(f"OSError: {str(e)} - handling gracefully.")
